def _headers(self, q: TargetQuery) -> dict[str, str]:
    headers = {}
    for name, value in self._config.headers.items():
        if value.startswith(SECRET_PREFIX):
            try:
                value = self._resolve(value)
            except Exception:
                raise TargetError(E.SECRET_UNRESOLVED, f"{value} did not resolve") from None
        headers[name] = value
    headers["X-AEVIS-Idempotency-Key"] = str(q.params.get("idempotency_key", q.query_id))
    headers["X-AEVIS-Attempt"] = str(q.params.get("attempt", 1))
    return headers
